const handlers=new Map();let cleanup=()=>{},stopSwitcher=()=>{},unsubscribe=()=>{},started=false,ctx=null,renderQueued=false,lastHash=null;
export function registerActions(namespace,actions) { if(handlers.has(namespace))throw new Error(`Actions already registered: ${namespace}`);handlers.set(namespace,actions); }
