 if(params.gradeId&&!s.grades.some(x=>x.id===params.gradeId))return 'missing';
 if(route.module==='public' && ['/course/:id','/teacher/:id','/explore/grade/:gradeId/subject/:subjectId'].includes(p))return null;
 if(params.subjectId&&!s.subjects.some(x=>x.id===params.subjectId))return 'missing';
 if(p==='/legal/:page'&&!['privacy','terms','refunds'].includes(params.page))return 'notFound';
 if(p.includes('/child/:id')){collection='students';id=params.id;action='child.read';}
 else if(p.includes('/inbox/:id')||p.includes('/messages/:id')){collection='conversations';id=params.id;action='conversation.read';}
 else if(p.includes('/course/:id')||p==='/course/:id'||p.includes('/courses/:id/edit')||params.courseId){collection='courses';id=params.id??params.courseId;action=route.module==='public'||route.module==='checkout'?'public.read':'course.read';}
 else if(p==='/teacher/:id'){const teacher=s.teachers.find(x=>x.id===params.id);return !teacher?'missing':teacher.application_status!=='approved'||teacher.account_status!=='active'?'resourceDenied':null;}
 else if(params.orderId){collection='orders';id=params.orderId;action='order.read';}
 else if(p==='/admin/finance/payouts/:id')return s.payout_batches.some(x=>x.id===params.id)?null:'missing';
