 for(const [key,values] of Object.entries(found?.route.queryValues??{}))if(query.has(key)&&!values.includes(query.get(key)))query.set(key,values[0]);
 // Visitors have no workspace shell; checkout and public routes use the public layout.
 const portal=role!=='visitor'&&(found?['student','guardian','teacher','assistant','admin'].includes(found.route.module):/^\/(student|guardian|teacher|assistant|admin)(\/|$)/.test(path));
 const layout=portal?portalLayout:publicLayout;let body,view;
 try {
  if(!found)body=fallback('notFound',ctx);
  else if(!found.route.roles.includes(role))body=fallback('roleDenied',ctx,{roles:found.route.roles});
  else { const denial=resourceGuard(found.route,ctx.params);if(denial)body=fallback(denial,ctx);else {view=found.route.view;body=view.render(ctx);} }
  if(!portal)body=found?.route.path==='/'?body:`<div class="container page-main">${body}</div>`;
  app.innerHTML=layout(body,ctx);
  if(view?.mount)cleanup=view.mount(app,ctx)??(()=>{});
 }catch(error){console.error('View render failed',error);cleanup();cleanup=()=>{};app.innerHTML=layout(`<div class="${portal?'':'container page-main'}">${fallback('viewError',ctx)}</div>`,ctx);}
 const title=found?.route.path==='/legal/:page'?t(ctx.params.page):L(found?.route.title??t('notFound'));document.title=title+' · '+t('brand');
 const changed=hash!==lastHash;lastHash=hash;
 if(!changed&&oldId&&document.getElementById(oldId)){const next=document.getElementById(oldId);next.focus();if(typeof next.setSelectionRange==='function'&&oldPosition!==null)try{next.setSelectionRange(oldPosition,oldPosition);}catch{}}
